using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Guards the layering of the solution so that business code (Domain, Application) never
/// reaches down into technical/infrastructure detail. These checks run against the built
/// assemblies, so they only make sense as part of a full build, not the fast per-save loop.
/// </summary>
public sealed class LayerDependencyTests
{
    private static readonly System.Reflection.Assembly DomainAssembly =
        typeof(PaymentAuthorization.Domain.Money).Assembly;

    private static readonly System.Reflection.Assembly ApplicationAssembly =
        typeof(PaymentAuthorization.Application.AuthorizePayment).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_Application_or_Infrastructure()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOnAny(
                "PaymentAuthorization.Application",
                "PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_Infrastructure()
    {
        var result = Types.InAssembly(ApplicationAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_depend_on_technical_frameworks()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOnAny(
                "System.Net.Http",
                "System.IO",
                "Microsoft.Extensions.DependencyInjection")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_technical_frameworks()
    {
        var result = Types.InAssembly(ApplicationAssembly)
            .Should()
            .NotHaveDependencyOnAny(
                "System.Net.Http",
                "System.IO",
                "Microsoft.Extensions.DependencyInjection")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        result.IsSuccessful
            ? string.Empty
            : "Offending types: " + string.Join(", ", result.FailingTypes?.Select(t => t.FullName) ?? []);
}
EOF
